function validate([operations, args]) {
  if (operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TwoSum' || args[0].length !== 0) return 'Start with TwoSum and no arguments.';
  if (operations.length - 1 > 10000) return 'At most 10^4 calls to add and find.';
  for (let i = 1; i < operations.length; i++) {
    const [x] = args[i];
    if (args[i].length !== 1 || !Number.isInteger(x)) return 'add and find each take one whole number.';
    if (operations[i] === 'add') {
      if (x < -100000 || x > 100000) return 'add takes a number from -10^5 to 10^5.';
    } else if (operations[i] === 'find') {
      if (x < -2147483648 || x > 2147483647) return 'find takes a 32-bit signed integer.';
    } else return 'Only add and find can follow the constructor.';
  }
  return null;
}

