class TwoSum {
  constructor() {
    this.counts = new Map();
  }

  add(number) {
    this.counts.set(number, (this.counts.get(number) || 0) + 1);
  }

  find(value) {
    for (const [number, count] of this.counts) {
      const complement = value - number;
      if (complement === number) {
        if (count >= 2) {
          return true;
        }
      } else if (this.counts.has(complement)) {
        return true;
      }
    }
    return false;
  }
}

